/// Create routes for state transitions.
pub fn create_bucket_transition_routes(service: Arc<BucketService>) -> Router {
    use axum::routing::post;

    Router::new()
        .route("/buckets/:id/transitions/lock", post(lock_transition))
        .route("/buckets/:id/transitions/unlock", post(unlock_transition))
        .route("/buckets/:id/transitions/archive", post(archive_transition))
        .route("/buckets/:id/transitions/restore", post(restore_transition))
        .route("/buckets/:id/transitions/delete", post(delete_transition))
        .with_state(service)
        .layer(axum::middleware::from_fn(backbone_core::http::correlation_middleware))
}

